head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gProcType;
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gAcptNo;
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;
scwin.gComAbbrv;
scwin.gPageSize = 50; //페이지 size
scwin.gTotalCnt = 0; //전체 row
scwin.gPageNoCnt = 10; //page 번호 개수
scwin.vCurrPageNo = 0; //현재 선택된 페이지번호

scwin.vScrenID = 'ULDSTF26609.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;

    /*
    //  기간 from~ to  셋팅			
    vCurDate = cGetToday("yyyymmdd");
    edt_FromDate.text = cGetMinusMonth(vCurDate.substring(0,4), vCurDate.substring(4,6), vCurDate.substring(6,8), 1); 	// 한달전 날짜
    edt_ToDate.text = cGetToday("yyyymmdd");		// 현재날짜

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode"+
    			"&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT"+
    			"&For=R&DEP_CD="+gDepCd ;		
    dts_dep.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode"+
    			"&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT"+
    			"&For=R&DEP_CD="+gDepCd ;
    dts_emp.Reset();
    */


    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !목록검색--;
클릭-- > function() {
    var vlength = $c.stf.getObjectValue(txb_isur_cd).length;
    if (vlength > 0 && vlength != 5) {
        $c.win.alert("회사코드 5자리를 올바르게 입력하십시오.");
        txb_isur_cd.focus();
        return;
    }
    fn_Search();
};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !목록검색--;
사용자;
클릭-- > function() {
    var url = "/SubmitStatus.do?method=listNSubmitInfo&inputMessageId=NSUBMIT_INFO_INOUT" + "&outputMessageId=NSUBMIT_INFO_INOUT" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&LIST_STAT=" + scwin.getChkValue(chb_ListStatCd) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_NSubmitList.DataID = encodeURI(url);
    dts_NSubmitList.reset();
    $c.cm.ShowWin(dts_NSubmitList);
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gIsurCd = dts_NSubmitList.getCellData(eval(obj), "ISUR_CD");
    scwin.gComAbbrv = dts_NSubmitList.getCellData(eval(obj), "COM_ABBRV");
    //alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};
scwin.fn_OpenNSubmitMgt = async function(obj) {
    if (obj == "N") {
        scwin.gIsurCd = "";
        scwin.gComAbbrv = "";
    }
    scwin.gProcType = obj;
    var url = "/dsclsrch/ULDSTF26610.gfm?ISUR_CD=" + scwin.gIsurCd + "&COM_ABBRV=" + scwin.gComAbbrv;
    var winTitle = "정기보고서 미제출법인 관리";
    await $c.frame.CreateDialogFrame("NSUBMITINFO1", url, winTitle, 200, 200, 700, 290, "window");
    scwin.gProcType = "";
};
scwin.grd_NSubmitList_OnDblClick = function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "NSUBMIT_RSN_NM1") {
        scwin.fn_OpenNSubmitMgt("M");
    } else if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.dts_NSubmitList_OnLoadError = function() {
    $c.stf.alert_error(dts_NSubmitList);
    $c.cm.CloseWin('', grd_NSubmitList);
};
scwin.dts_NSubmitList_OnLoadCompleted = function(rowcount) {
    if (dts_NSubmitList.errorMsg) {
        $c.win.alert(dts_NSubmitList.errorMsg);
    }
    $c.cm.CloseWin(rowcount, grd_NSubmitList);
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
};
scwin.img_toExcel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_NSubmitList, "정기보고서 미제출법인 목록", "", "8");
};
scwin.img_search_onclick = function() {
    fn_CheckCond();
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.btn_input_onclick = function() {
    scwin.gProcType = "N";
    //frame.CreateDialogFrame("gform", "/dsclsrch/ULDSTF26610.gfm", "정기보고서 미제출법인 관리" ,10, 10, 700, 500, "window" );
    scwin.fn_OpenNSubmitMgt("N");
    scwin.gProcType = "";
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    fn_CheckCond();
};
